	protected FeatureSet read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created FeatureSet" );

		FeatureSet entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read FeatureSet with primary key" );
		msg.append( featureSetId );
		
		FeatureSetFetchOneSummary fetchOneSummary = new FeatureSetFetchOneSummary( featureSetId );

		try {
			entity = FeatureSetService.getFeatureSetInstance().getFeatureSet( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found FeatureSet " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a FeatureSet.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a FeatureSet." );

		StringBuilder msg = new StringBuilder( "Failed to update a FeatureSet : " );        
		FeatureSet entity = read();
		UpdateFeatureSetCommand command = generateUpdateCommand();
		command.setFeatureSetId(entity.getFeatureSetId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created FeatureSet." );

			// for use later on...
			featureSetId = entity.getFeatureSetId();

			FeatureSetService proxy = FeatureSetService.getFeatureSetInstance();  

			proxy.updateFeatureSet( command ).get();

			LOGGER.info( "-- Successfully saved FeatureSet - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + featureSetId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a FeatureSet.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created FeatureSet." );

		FeatureSet entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read FeatureSet with id " + featureSetId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read FeatureSet with id " + featureSetId );

			throw e;
		}

		try{
			FeatureSetService.getFeatureSetInstance().delete( new DeleteFeatureSetCommand( entity.getFeatureSetId() ) ).get();
			LOGGER.info( "-- Successfully deleted FeatureSet with id " + featureSetId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete FeatureSet with id " + featureSetId );

			throw e;
		}
	}

	/**
	 * get all FeatureSets.
	 */
	protected List<FeatureSet> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of FeatureSets:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all FeatureSet : " );        
		List<FeatureSet> collection  = new ArrayList<>();

		try {
			// call the static get method on the FeatureSetService
			collection = FeatureSetService.getFeatureSetInstance().getAllFeatureSet();
			assertNotNull( collection, "An Empty collection of FeatureSet was incorrectly returned.");
			
			// Now print out the values
			FeatureSet entity = null;            
			Iterator<FeatureSet> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getFeatureSetId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

